function bindExports(){document.getElementById('liveDiscoveryExport').onclick=()=>{const cols=[{key:'channel_title',label:'博主'},{key:'channel_id',label:'Channel ID'},{key:'channel_url',label:'频道网址'},{key:'subscribers',label:'订阅数'},{key:'country',label:'国家/地区'},{key:'country_source',label:'国家证据'},{key:'best_video_title',label:'最佳命中视频'},{key:'best_video_id',label:'Video ID'},{key:'best_video_views',label:'视频播放量'},{key:'discovery_score',label:'发现评分'},{key:'tier',label:'评级'},{key:'query_coverage',label:'Query Coverage'},{key:'matched_queries',label:'命中 Query'},{key:'identity',label:'身份标签'},{key:'freshness',label:'首次/重复发现'},{key:'workflow',label:'处理状态'}];const rows=liveFilteredAll().map(c=>({channel_title:c.channel_title||'',channel_id:c.channel_id||'',channel_url:`https://www.youtube.com/channel/${c.channel_id||''}`,subscribers:c.subscribers,country:c.country_resolved||c.country_api||'',country_source:c.country_source||'',best_video_title:c.title||'',best_video_id:c.video_id||'',best_video_views:c.views,discovery_score:c.pre_score,tier:c.opportunity_tier,query_coverage:c.query_coverage||0,matched_queries:(c.matched_queries||[]).join(' | '),identity:(()=>{const f=byId.get(c.channel_id);if(!f)return '尚未入库';return [f.partnered_ugphone?'合作过博主':'未合作博主',f.ldcloud_creator?'LDCloud合作博主':'',f.redfinger_creator?'RedFinger合作博主':'',f.vsphone_creator?'VSPhone合作博主':'',f.suspected_inactive_partner?'疑似不再合作':''].filter(Boolean).join(' | ')})(),freshness:Number(c.discovery_run_count||1)<=1?'首次发现':`重复发现 × ${c.discovery_run_count}`,workflow:c.workflow_label||'未处理'}));CDHExport.rows('discovery_current_creators.xlsx','本次搜索结果',cols,rows).catch(e=>alert(e.message))};document.getElementById('savedCreatorExport').onclick=()=>CDHExport.source('discovery_creators','discovery_creators.xlsx','Discovery Creators',{search:document.getElementById('savedCreatorSearch').value,conditions:creatorConditions,sort:document.getElementById('savedCreatorSort').value,dir:document.getElementById('savedCreatorSortDir').value}).catch(e=>alert(e.message));document.getElementById('savedDiscoveryExport').onclick=()=>CDHExport.source('discovery_videos','discovery_video_hits.xlsx','Discovery Video Hits',{search:document.getElementById('savedDiscoverySearch').value,conditions:savedConditions,sort:document.getElementById('savedDiscoverySort').value,dir:document.getElementById('savedDiscoverySortDir').value}).catch(e=>alert(e.message))}
function bindControls(){document.getElementById('liveDiscoverySearch').oninput=()=>{selectedLive.clear();livePage=1;renderLive()};document.getElementById('liveDiscoverySort').onchange=()=>{livePage=1;renderLive()};document.getElementById('liveDiscoverySortDir').onchange=()=>{livePage=1;renderLive()};document.getElementById('liveDiscoveryPageSizeConfirm').onclick=()=>{liveSize=CDHTableTools.pageSize(document.getElementById('liveDiscoveryPageSize'),liveSize);document.getElementById('liveDiscoveryPageSize').value=String(liveSize);livePage=1;renderLive()};document.getElementById('liveDiscoveryAddFilter').onclick=()=>addLive();document.getElementById('liveDiscoveryApplyFilter').onclick=()=>{selectedLive.clear();liveFilters=readLive();livePage=1;renderLive()};document.getElementById('liveDiscoveryClearFilter').onclick=()=>{selectedLive.clear();liveFilters=[];liveFilterBox.innerHTML='';addLive();livePage=1;renderLive()};document.getElementById('savedDiscoverySearch').oninput=()=>{savedPage=1;loadSaved()};document.getElementById('savedDiscoverySort').onchange=()=>{savedPage=1;loadSaved()};document.getElementById('savedDiscoverySortDir').onchange=()=>{savedPage=1;loadSaved()};document.getElementById('savedDiscoveryPageSizeConfirm').onclick=()=>{savedSize=CDHTableTools.pageSize(document.getElementById('savedDiscoveryPageSize'),savedSize);document.getElementById('savedDiscoveryPageSize').value=String(savedSize);savedPage=1;loadSaved()};document.getElementById('savedDiscoveryAddFilter').onclick=()=>addSaved();document.getElementById('savedDiscoveryApplyFilter').onclick=()=>{savedConditions=readSaved();savedPage=1;loadSaved()};document.getElementById('savedDiscoveryClearFilter').onclick=()=>{savedConditions=[];savedFilterBox.innerHTML='';addSaved();savedPage=1;loadSaved()};document.getElementById('savedCreatorSearch').oninput=()=>{selectedSavedCreators.clear();creatorPage=1;loadSavedCreator()};document.getElementById('savedCreatorSort').onchange=()=>{creatorPage=1;loadSavedCreator()};document.getElementById('savedCreatorSortDir').onchange=()=>{creatorPage=1;loadSavedCreator()};document.getElementById('savedCreatorPageSizeConfirm').onclick=()=>{creatorSize=CDHTableTools.pageSize(document.getElementById('savedCreatorPageSize'),creatorSize);document.getElementById('savedCreatorPageSize').value=String(creatorSize);creatorPage=1;loadSavedCreator()};document.getElementById('savedCreatorAddFilter').onclick=()=>addCreatorCond();document.getElementById('savedCreatorApplyFilter').onclick=()=>{selectedSavedCreators.clear();creatorConditions=readCreatorCond();creatorPage=1;loadSavedCreator()};document.getElementById('savedCreatorClearFilter').onclick=()=>{selectedSavedCreators.clear();creatorConditions=[];creatorFilterBox.innerHTML='';addCreatorCond();creatorPage=1;loadSavedCreator()};bindExports();bindBatchControls()}
document.getElementById('discoverBtn').onclick=async()=>{const q=document.getElementById('discoverQuery').value.trim(),st=document.getElementById('discoverStatus'),look=document.getElementById('discoverLookback').value;if(!q)return alert('请输入游戏名称');let from='',to='';if(look==='custom'){from=document.getElementById('discoverFromDate').value;to=document.getElementById('discoverToDate').value;if(!from||!to)return alert('精确时间需要同时填写开始日期和结束日期');if(from>to)return alert('开始日期不能晚于结束日期')}const queries=buildExpandedQueries(q),lang=currentQueryLang(),searchLang=(QP.languages?.[lang]||{}).search_language||lang;try{st.textContent=`正在执行 ${queries.length} 个 Query，并补充视频/频道指标…`;const country=document.getElementById('discoverCountry').value,group=document.getElementById('discoverRegionGroup').value,payload={query:q,queries,language:searchLang,query_language:lang,search_source:document.getElementById('discoverSource').value,lookback_days:look&&look!=='custom'?look:null,from_date:from,to_date:to,target_country:country,target_group:country?'':group,region:country||null,max_results:Number(document.getElementById('discoverMax').value),max_queries:Number(QP.max_queries_per_search||80)},x=window.CDHJobs?await CDHJobs.run('discovery_search',payload):await post('/api/discover',payload);liveResults=x.results||[];selectedLive.clear();livePage=1;document.getElementById('liveDiscoverySort').value='score';document.getElementById('liveDiscoverySortDir').value='desc';renderLive();const errs=(x.errors||[]).length;st.textContent=`搜索批次 ${x.run_id||'—'}：已执行 ${x.query_count||0}/${x.queries_requested?.length||queries.length} 个 Query；命中视频 ${x.hits||0} 条，去重后博主 ${x.unique_creators||0} 个；博主结果与视频命中均已即时保存${errs?`；${errs} 个 Query 执行失败或被配额中止`:''}。`;savedPage=1;creatorPage=1;await Promise.all([loadSaved(),loadSavedCreator()])}catch(e){st.textContent=e.message}};
savedStaticRows=[...document.querySelectorAll('#savedDiscoveryRows tr[data-search]')];creatorStaticRows=[...document.querySelectorAll('#savedCreatorRows tr[data-search]')];savedStaticRows.forEach(r=>r.style.display='none');creatorStaticRows.forEach(r=>r.style.display='none');document.getElementById('savedDiscoverySummary').textContent='正在检测交互服务并读取第一页…';document.getElementById('savedCreatorSummary').textContent='正在检测交互服务并读取第一页…';setupGeography();setupDiscoverTime();setupQueryExpansion();addLive();addSaved();addCreatorCond();bindControls();document.getElementById('liveDiscoveryPageSize').value='30';document.getElementById('savedDiscoveryPageSize').value='30';document.getElementById('savedCreatorPageSize').value='30';fetch('/api/ping').then(r=>r.ok?r.json():null).then(async x=>{interactive=!!x;if(interactive){document.getElementById('interactiveNote').innerHTML='<b>交互模式已开启。</b> 搜索、Query Expansion、处理状态、批量操作和完整 XLSX 导出可直接使用；写库后当前数据会直接重读 SQLite。';await refreshCreatorFacts();renderLive();await hydrateQueryProfile();await Promise.all([loadSaved(),loadSavedCreator()]);bindBatchControls()}else throw new Error()}).catch(()=>{document.getElementById('interactiveNote').innerHTML='<b>当前为静态只读模式。</b> 可查看快照与历史发现；完整搜索、写入和 XLSX 导出请使用 <span class="mono">start-dashboard.cmd</span> 打开交互模式。';document.getElementById('discoverBtn').disabled=true;renderSavedStatic();renderCreatorStatic()});window.addEventListener('focus',()=>{if(interactive)refreshCreatorFacts().then(()=>{renderLive();loadSavedCreator()}).catch(()=>{})});window.addEventListener('storage',e=>{if(interactive&&e.key==='cdh-data-revision')refreshCreatorFacts().then(()=>{renderLive();loadSavedCreator()}).catch(()=>{})});renderLive();
